// DrCurlEngine -- the libcurl wrapper. The binary's own members:
//   _ZN12DrCurlEngineC2Ev                                        @0x1ed300
//   _ZN12DrCurlEngineD2Ev                                        @0x1ed314
//   _ZN12DrCurlEngine4initEv                                     @0x1ed324
//   _ZN12DrCurlEngine6writerEPcjjPSs                             @0x1ed2e4
//   _ZN12DrCurlEngine7performERK13DrCurlRequestRSs               @0x1ed3e4
//   _ZN12DrCurlEngine7performERKSsS1_RSsN13DrCurlRequest10HttpMethodE  @0x1ed5f8
// The second perform is the one DrRpcEngine::perform calls.
class DrCurlRequest
{
public:
    // _ZN13DrCurlRequest10HttpMethodE -- a nested enum in the binary, and the
    // last parameter of DrCurlEngine::perform(string,string,string&,HttpMethod).
    // The enumerator names are not recoverable from the signature alone.
    // TODO(recon): name the HTTP verbs once a call site fixes the order.
    enum HttpMethod
    {
        HTTP_METHOD_GET = 0,
        HTTP_METHOD_POST = 1
    };

    static int getField(...);
    static int getPostFields(...);
    static int getSortedFields(...);
    static int getUrl(...);
    static int setField(...);
};

class DrCurlEngine
{
public:
    static int init(...);
    static int writer(char* theBuffer, unsigned int theSize, unsigned int theCount, Sexy::String* theOutput);
    static int perform(DrCurlRequest const& theRequest, Sexy::String& theResponse);
    static int perform(Sexy::String const& theUrl, Sexy::String const& theBody,
                       Sexy::String& theResponse, DrCurlRequest::HttpMethod theMethod);
};

