class TodTriangleGroup
{
public:
    // The binary's three members:
    //   _ZN16TodTriangleGroupC2Ev                                  @0x205268
    //   _ZN16TodTriangleGroup9DrawGroupEPN4Sexy8GraphicsE           @0x2052ac
    //   _ZN16TodTriangleGroup11AddTriangleEPN4Sexy8GraphicsEPNS0_5ImageE
    //       RKNS0_11SexyMatrix3ERKNS0_5TRectIiEERKNS0_5ColorEiSB_   @0x205360
    //
    // These are NON-STATIC. The absence of a receiver in the mangled name means
    // nothing (the Itanium ABI never encodes `this`), and the bodies are
    // explicit about it: AddTriangle's decompiled signature names its first
    // parameter as the group and writes its vertex cursor and graphics pointer.
    // DrawGroup is called on that same object.
    //
    // Call sites keep the member form: group->DrawGroup(graphics) and
    // group->AddTriangle(graphics, ...).
    TodTriangleGroup();
    int DrawGroup(Sexy::Graphics* theGraphics);
    // SexyMatrix3 is a GLOBAL-namespace type (CoreTypes.h declares it outside
    // `namespace Sexy`), so it is spelled without the Sexy:: prefix here --
    // `Sexy::SexyMatrix3` does not exist.
    //
    // The last parameter is a TRect, not a Color. The mangled name ends
    // `...RKNS0_5ColorEiSB_`, and `SB_` is the substitution `S_` (which the
    // preceding `RKNS0_5TRectIiEE` bound to `Sexy::TRect<int>`) plus `B_`
    // (const reference) -- so it is `Sexy::TRect<int> const&`. IDA's own
    // demangling of 0x205360 agrees: `..., Sexy::Color const&, int,
    // Sexy::TRect<int> const&`. The transcription had written a second Color,
    // which made every call site in Reanimation::DrawTrack a C2664.
    int AddTriangle(Sexy::Graphics* theGraphics, Sexy::Image* theImage,
                    SexyMatrix3 const& theMatrix, Sexy::TRect<int> const& theSrc,
                    Sexy::Color const& theColor, int theVertexCount,
                    Sexy::TRect<int> const& theClip);
};

