// NOTE: there is deliberately no global named UTF8 here. It was a
// transcription artefact, and a global variable of that name HIDES the class
// UTF8 (the real symbol is _ZN4UTF813filterUnicodeERKSs @0x1f46cc), so every
// `UTF8::filterUnicode` in the tree failed to resolve. Nothing read the global.

// ---------------------------------------------------------------------------
// File-scope globals the game bodies reference by bare name.
//
// The decompiler printed these unqualified (no class scope), so they live at
// file scope here too. Each carries the address and kind the binary gives it;
// their storage is in Sexy/ReconData.cpp.
// ---------------------------------------------------------------------------

// TodStringListFormat -- the {name, font, color, offset, flags} record the
// framework's string-list colour table is made of (see the PC build's
// LawnApp.cpp: a name String, a font pointer, a Color, an int and an unsigned
// flags word -- 7 words).
struct TodStringListFormat
{
    Sexy::String    mName;
    Sexy::Font*     mFont;
    Sexy::Color     mColor;
    int             mOffset;
    unsigned int    mFlags;
};


// gLawnStringFormats @0x715b90, initialized with all 14 original formats.
extern TodStringListFormat gLawnStringFormats[14];

// gTodStringFormats / gTodStringFormatCount -- the framework's active table,
// written by TodStringListSetColors (see TodStringListSetColors @0x2001e0).
extern TodStringListFormat *gTodStringFormats;
extern int gTodStringFormatCount;

// gArtChallengeWallnut -- the 9x9 challenge art grid, indexed as
// `gArtChallengeWallnut[9 * row + column]`.
extern const int gArtChallengeWallnut[9 * 9];

