// (initial value 268).
extern int gCreditsTimingCount;

// ---------------------------------------------------------------------------
// The game's parameter tables and session helpers.
//
// The PC reference source declares these in LawnApp.h (LawnApp.cpp:45/152/261/
// 407 and LawnApp.h:483-486) and nothing in this tree did, so LawnApp.cpp
// reported C2065 for each. Particle and trail tables use the actual loader
// records, with the original resource paths restored from the TV binary.
// gLawnReanimationArray is the 178-row TV table, one ReanimationParamRecord
// per ReanimationType.
//
// FoleyParams is transcribed, because TodFoley.cpp does read its fields. Layout
// from the authoritative header PvZ\TodLib\Common\TodFoley.h and confirmed by
// the bodies: PlayFoley reads the pitch range at +4, PlayFoleyPitch reads the
// sound ids at +8 + 4 * variation, and GamePause / RehookupSoundWithMusicVolume
// read the flag word at +48.
// ---------------------------------------------------------------------------
class FoleyParams
{
public:
    FoleyType mFoleyType;      // +0x00
    float mPitchRange;         // +0x04
    int *mSfxID[10];           // +0x08 .. +0x2F
    unsigned int mFoleyFlags;  // +0x30
    // size 0x34
};

// Layout: 4 (type) + 4 (pitch range) + 40 (ten sound ids) + 4 (flags).

extern FoleyParams        gLawnFoleyParamArray[];
extern ParticleParamRecord gLawnParticleArray[NUM_PARTICLE_EFFECTS];
extern TrailParamRecord   gLawnTrailArray[1];
extern ReanimationParamRecord gLawnReanimationArray[];

// The table LookupFoley indexes, one entry per FoleyType, and its length
// (gFoleyParamArraySize is declared in ReconData.h and defined in
// ReconGlobals.cpp). TodFoleyInitialize sets both in the authoritative source.
extern FoleyParams        *gFoleyParamArray;

// @0x... -- the binary's LookupFoley, i.e. `&gFoleyParamArray[theFoleyType]`
// (PvZ-src\TodLib\Common\TodFoley.cpp:32). TodFoley.cpp defines it.
//
FoleyParams *LookupFoley(FoleyType theFoleyType);

// LawnApp.cpp:1579 in the PC source; the binary exports _Z14BetaSubmitFuncv.
void BetaSubmitFunc();

// _ZN15LawnSessionTaskD2Ev @0x2b25d4 / _ZTV15LawnSessionTask @0x687980 -- a
// session task base class. LawnApp.cpp only declares pointers to it, but
// LawnSession::HandleTask @0x1EBCEC calls its second non-destructor vtable slot,
// so the interface has to be complete here for that call to be written as a real
// virtual call.
//
// The vtable is the authority for the four member names: LawnSessionTask itself
// leaves slots 2..5 as __cxa_pure_virtual, and LawnBaseTask's vtable at 0x6879a0
// fills three of them in:
//   [2] __cxa_pure_virtual in LawnBaseTask too; derived classes supply it:
//       0x2bed79 LoginTask::Run, 0x2bc6dd LogoutTask::Run,
//       0x2bd3ad UseToolTask::Run, 0x2bd095 DebugAddMoney::Run
//       -> virtual void Run()
//   [3] 0x2b25f1 LawnBaseTask::Failed          (returns the byte at +4)
//   [4] 0x2b25ed LawnBaseTask::GetLastError    (returns the word at +8)
//   [5] 0x2b2695 LawnBaseTask::GetLastErrorMsg (returns the String at +12 by
//       value: the body is a String copy into the caller's return slot)
class LawnSessionTask
{
public:
    virtual ~LawnSessionTask();

    virtual void Run() = 0;
    virtual bool Failed() = 0;
    virtual int  GetLastError() = 0;
    virtual Sexy::String GetLastErrorMsg() = 0;
};

// The test-dialog table LawnApp's debug path walks. Neither name appears in the
// PC reference source or in _recon; the bodies only use them as a list and a
// count, so they are modelled that way.
// TODO(recon): recover the real record layout from the binary.
struct TestDialogInfo   { int mFields[4]; };
extern TestDialogInfo   mTestInfos[];
extern int              gTestInfoCount;

// ---------------------------------------------------------------------------
// The app hooks. The PC reference source declares these in TodCommon.h:178-181
// and assigns them in WinMain (LawnApp.cpp:446-449):
//
//     gGetCurrentLevelName    = LawnGetCurrentLevelName;
//     gAppCloseRequest        = LawnGetCloseRequest;
//     gAppHasUsedCheatKeys    = LawnHasUsedCheatKeys;
//     gExtractResourcesByName = Sexy::ExtractResourcesByName;
//
// They are function POINTERS the framework calls into the game, so the tree
// needs both halves: the pointer globals and the game-side implementations.
// ---------------------------------------------------------------------------
extern bool         (*gAppCloseRequest)();
extern bool         (*gAppHasUsedCheatKeys)();
extern Sexy::String (*gGetCurrentLevelName)();
extern bool         (*gExtractResourcesByName)(Sexy::ResourceManager* theResourceManager,
                                               const char* theName);

// The game-side halves the pointers above are assigned from. The PC source has
// them in Lawn/LawnApp.cpp; here they are declared alongside so the assignment
// in LawnApp's initialisation can name them.
bool          LawnGetCloseRequest();
bool          LawnHasUsedCheatKeys();
Sexy::String  LawnGetCurrentLevelName();
namespace Sexy { bool ExtractResourcesByName(ResourceManager* theResourceManager,
                                             const char* theName); }

// NOTE: a block of `namespace Sexy` free-function declarations was added here
// and then reverted. It guessed signatures from the linker's demangled output,
// and two of the guesses collided with declarations that already existed with
// different types -- `SetAppDataFolder` (already `void`, guessed `int`) and
// `ImageLib::GetImage` (already four parameters, guessed two) -- which broke
// SexyAppBase.cpp with C2556/C2371/C2660.
//
// The underlying problem is real and still open: functions such as
// `Sexy::FileExists(Sexy::String const&)` are reached by call sites but declared
// nowhere, because the transcriber mapped them onto same-named members of other
// classes. Adding them needs each one's exact signature, taken from
// `build/unresolved.txt` (which records the mangled name the linker asked for)
// rather than from the readable form. See tools/unresolved.py.
